import { useState } from 'react';
import { useStore } from '@/store';
import Card from '@/components/ui/Card';
import EmptyState from '@/components/ui/EmptyState';
import { Trash2, RotateCcw, XCircle } from 'lucide-react';

const fmt = (n: number) => Math.round(n).toLocaleString('en-US');
const dt = (d: string) => new Date(d).toLocaleDateString('en-US', { year: 'numeric', month: '2-digit', day: '2-digit' });

type Tab = 'products' | 'customers' | 'suppliers' | 'cashboxes' | 'sales' | 'purchases' | 'expenses' | 'cashMovements';

const tabs: { key: Tab; label: string }[] = [
  { key: 'products', label: 'المنتجات' },
    { key: 'customers', label: 'العملاء' },
      { key: 'suppliers', label: 'الموردين' },
        { key: 'cashboxes', label: 'الصناديق' },
          { key: 'sales', label: 'المبيعات' },
            { key: 'purchases', label: 'المشتريات' },
              { key: 'expenses', label: 'المصروفات' },
                { key: 'cashMovements', label: 'السندات' },
                ];

                export default function Trash() {
                  const s = useStore();
                    const [tab, setTab] = useState<Tab>('products');

                      const list = s.trash[tab] || [];

                        const restoreFn: Record<Tab, (id: string) => void> = {
                            products: s.restoreProduct,
                                customers: s.restoreCustomer,
                                    suppliers: s.restoreSupplier,
                                        cashboxes: s.restoreCashBox,
                                            sales: s.restoreSale,
                                                purchases: s.restorePurchase,
                                                    expenses: s.restoreExpense,
                                                        cashMovements: s.restoreCashMovement,
                                                          };

                                                            const deleteFn: Record<Tab, (id: string) => void> = {
                                                                products: s.permanentDeleteProduct,
                                                                    customers: s.permanentDeleteCustomer,
                                                                        suppliers: s.permanentDeleteSupplier,
                                                                            cashboxes: s.permanentDeleteCashBox,
                                                                                sales: s.permanentDeleteSale,
                                                                                    purchases: s.permanentDeletePurchase,
                                                                                        expenses: s.permanentDeleteExpense,
                                                                                            cashMovements: s.permanentDeleteCashMovement,
                                                                                              };

                                                                                                const renderDetails = (item: any) => {
                                                                                                    switch (tab) {
                                                                                                          case 'products':
                                                                                                                  return (
                                                                                                                            <div className="text-small text-text-secondary space-y-1 mt-2">
                                                                                                                                        <p>باركود: {item.barcode || '-'}</p>
                                                                                                                                                    <p>الكمية: {fmt(item.stockQuantity || item.quantity || 0)}</p>
                                                                                                                                                                <p>سعر الشراء: {fmt(item.purchasePrice || 0)}</p>
                                                                                                                                                                            <p>سعر البيع: {fmt(item.sellingPrice || 0)}</p>
                                                                                                                                                                                        {item.unit && <p>الوحدة: {item.unit}{item.boxQty ? ` (${item.boxQty} حبة)` : ''}</p>}
                                                                                                                                                                                                  </div>
                                                                                                                                                                                                          );
                                                                                                                                                                                                                case 'customers':
                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                  <div className="text-small text-text-secondary space-y-1 mt-2">
                                                                                                                                                                                                                                              {item.phone && <p>هاتف: {item.phone}</p>}
                                                                                                                                                                                                                                                          {item.address && <p>عنوان: {item.address}</p>}
                                                                                                                                                                                                                                                                      <p>الرصيد: {fmt(item.balance || 0)}</p>
                                                                                                                                                                                                                                                                                  {item.notes && <p>ملاحظات: {item.notes}</p>}
                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                          case 'suppliers':
                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                            <div className="text-small text-text-secondary space-y-1 mt-2">
                                                                                                                                                                                                                                                                                                                                        {item.phone && <p>هاتف: {item.phone}</p>}
                                                                                                                                                                                                                                                                                                                                                    {item.address && <p>عنوان: {item.address}</p>}
                                                                                                                                                                                                                                                                                                                                                                <p>الرصيد: {fmt(item.balance || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                            {item.notes && <p>ملاحظات: {item.notes}</p>}
                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                    case 'cashboxes':
                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="text-small text-text-secondary space-y-1 mt-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>الرصيد: {fmt(item.balance || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                              <p>تاريخ الإنشاء: {dt(item.createdAt)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      case 'sales':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="text-small text-text-secondary space-y-1 mt-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>النوع: {item.type === 'cash' ? 'نقدي' : 'آجل'}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p>التاريخ: {dt(item.createdAt)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p>الإجمالي: {fmt(item.total || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p>المدفوع: {fmt(item.paid || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>المتبقي: {fmt(item.remaining || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {item.items && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="mt-1"><p className="font-semibold">المنتجات:</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {item.items.map((i: any, idx: number) => <p key={idx}>• {i.productName} ×{i.quantity} = {fmt(i.total)}</p>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                case 'purchases':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="text-small text-text-secondary space-y-1 mt-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p>التاريخ: {dt(item.createdAt)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p>الإجمالي: {fmt(item.total || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p>المدفوع: {fmt(item.paid || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>المتبقي: {fmt(item.remaining || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {item.items && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="mt-1"><p className="font-semibold">المنتجات:</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {item.items.map((i: any, idx: number) => <p key={idx}>• {i.productName} ×{i.quantity} = {fmt(i.total)}</p>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              case 'expenses':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="text-small text-text-secondary space-y-1 mt-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p>التاريخ: {item.date ? dt(item.date) : dt(item.createdAt)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p>المبلغ: {fmt(item.amount || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {item.notes && <p>ملاحظات: {item.notes}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            case 'cashMovements':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const owner = s.customers.find((c: any) => c.id === item.referenceId) || s.suppliers.find((sup: any) => sup.id === item.referenceId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="text-small text-text-secondary space-y-1 mt-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>النوع: {item.type === 'deposit' ? '🟢 سند قبض' : '🔴 سند صرف'}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p>التاريخ: {dt(item.createdAt)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p>المبلغ: {fmt(item.amount || 0)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {owner && <p>الحساب: {owner.name}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>الصندوق: {s.cashBoxes.find((b: any) => b.id === item.cashBoxId)?.name || ''}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {item.description && <p>ملاحظات: {item.description}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      default:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="page-container">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <h1 className="page-title">سلة المحذوفات</h1>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="flex gap-1 overflow-x-auto mb-4 pb-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {tabs.map((t) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button key={t.key} onClick={() => setTab(t.key)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className={`px-3 py-2 rounded-btn text-small font-semibold whitespace-nowrap transition-colors ${tab === t.key ? 'bg-primary text-white' : 'bg-primary-light text-primary'}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {t.label}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {s.trash[t.key]?.length > 0 && <span className="mr-1 bg-white text-primary rounded-full px-1.5 text-xs">{s.trash[t.key].length}</span>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {list.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <EmptyState message="لا توجد عناصر محذوفة" icon={<Trash2 size={64} strokeWidth={1.5} />} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="space-y-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {[...list].reverse().map((item: any) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Card key={item.id} accent>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex items-start justify-between">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h3 className="font-semibold text-body">{item.name || item.title || `#${item.id?.slice(-6)}`}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {renderDetails(item)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex gap-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button onClick={() => restoreFn[tab](item.id)} className="flex items-center gap-1 px-3 py-1.5 bg-success/10 text-success rounded-btn text-small font-semibold"><RotateCcw size={14} />استعادة</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button onClick={() => { if (confirm('هل أنت متأكد من الحذف النهائي؟ لا يمكن التراجع.')) deleteFn[tab](item.id); }} className="flex items-center gap-1 px-3 py-1.5 bg-danger/10 text-danger rounded-btn text-small font-semibold"><XCircle size={14} />حذف نهائي</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }